using System.Diagnostics;
using Cosmos.EffectAlgebra;
using Xunit;

namespace Cosmos.EffectAlgebra.Tests;

/// <summary>
/// 迭代16 — 规模/性能不回归守护（§3.3.1/§3.3.2/§9.1/§3.1.5a）。
/// 目的：证明 L1 在大规模 Signature 下 net/Peak/Deviation 仍正确、非指数增长、
///   非负溢出（溢出保守 ⇒ ⊤）、且不崩溃（无 NaN/∞/抛异常）。
/// 规模常量见 <see cref="N"/>/<see cref="SmallN"/>；所有断言可证伪（回归必红）。
/// 不引魔法数：规模、性能预算、size 均为命名常量。
/// </summary>
public class ScaleGuardTests
{
    private const int N = 5000;            // §3.3.1 大签名规模（occupy 数量级）
    private const int SmallN = 2000;       // §9.1 大输入规模（Deviation 每签名 Claim 数）
    private const int PerfN = 5000;        // §3.3.1 性能软约束规模
    private const int PerfBudgetMs = 2000; // §3.3.1 性能宽松上界（弱约束，非硬超时）
    private const ulong UnitSize = 1;      // §3.3.1 单值 size
    private const ulong PeakUnit = 100;    // §3.3.2 单值 size（峰值求和项）

    private static readonly ScopeId GlobalScope = new ScopeId.Global();

    // §3.3.1 — 构造 n 个 occupy claim（同资源），mode 全部 create，size 精确 [s,s]。
    // 纯 create 的 joined net = [s,s]（lo=s>0）⇒ IsConserved 必 false（泄漏，fail-closed 报警）。
    private static Signature BuildPureCreates(ResourceId res, int n, ulong s)
    {
        var claims = new Claim[n];
        for (int i = 0; i < n; i++)
            claims[i] = new Claim(Kind.Occupy, res, Mode.Create, GlobalScope, Interval.Exact(s));
        return Signature.Of(claims);
    }

    // §3.3.1 — 构造 2n 个 occupy claim（同资源），n 个 create + n 个 release 交替，size 精确 [s,s]。
    // create[+s] 与 release[−s] 抵消 ⇒ joined net = [−s,s]（含 0）⇒ IsConserved true（闭合，不报警）。
    private static Signature BuildBalanced(ResourceId res, int n, ulong s)
    {
        var claims = new Claim[2 * n];
        for (int i = 0; i < 2 * n; i++)
        {
            var mode = (i % 2 == 0) ? Mode.Create : Mode.Release;
            claims[i] = new Claim(Kind.Occupy, res, mode, GlobalScope, Interval.Exact(s));
        }
        return Signature.Of(claims);
    }

    /// <summary>§3.3.1 — 大签名 net 守恒正确：5000 个 create+release 交替（含匹配释放）⇒ IsConserved true；
    /// 5001 个纯 create（无匹配释放，相对平衡多一个 acquire）⇒ IsConserved false。断言不抛、不超时。</summary>
    [Fact]
    public void LargeSignature_NetConservation_Correct()
    {
        var res = new ResourceId.Memory(1);

        // 平衡：2500 create + 2500 release ⇒ joined net 含 0 ⇒ 守恒
        var balanced = BuildBalanced(res, N / 2, UnitSize);
        var balancedNet = NetTable.Compute(balanced, GlobalScope);
        Assert.True(balancedNet.IsConserved(res)); // §3.3.1 DO-9：含 0 ⇒ 不报警

        // 泄漏：5001 纯 create（无 release）⇒ joined net = [1,1]，lo>0 ⇒ 不守恒（fail-closed 报警）
        var leaked = BuildPureCreates(res, N + 1, UnitSize);
        var leakedNet = NetTable.Compute(leaked, GlobalScope);
        Assert.False(leakedNet.IsConserved(res)); // §3.3.1 DO-9：净占用 > 0 ⇒ 报警
    }

    /// <summary>§3.3.2 — 大签名 Peak 正确：5000 个非 release occupy（size [100,100]）⇒ Peak.Value == 100*5000；
    /// 其中 2500 个为 release 时被排除 ⇒ Peak.Value == 100*2500（仅算 mode≠release）。</summary>
    [Fact]
    public void LargeSignature_Peak_Correct()
    {
        var res = new ResourceId.Memory(2);

        // 全 create occupy（mode≠release）⇒ 求和 100*5000
        var allCreate = BuildPureCreates(res, N, PeakUnit);
        Assert.Equal(NatStar.Of(PeakUnit * (ulong)N), Peak.Compute(allCreate, GlobalScope)); // §3.3.2 size 求和

        // 半 release 半 create ⇒ release 被排除，仅 2500 个 create 计入 ⇒ 100*2500
        var half = new Claim[N];
        for (int i = 0; i < N; i++)
        {
            var mode = (i % 2 == 0) ? Mode.Create : Mode.Release; // §3.3.2 c.mode≠release：release 不贡献峰值
            half[i] = new Claim(Kind.Occupy, res, mode, GlobalScope, Interval.Exact(PeakUnit));
        }
        var mixed = Signature.Of(half);
        Assert.Equal(NatStar.Of(PeakUnit * (ulong)(N / 2)), Peak.Compute(mixed, GlobalScope)); // release 已排除
    }

    /// <summary>§9.1 — Deviation 大输入不崩：两签名各 2000 个 occupy（expected/actual 全 [1,1] 同资源）⇒ 有限小偏差（≈0），
    /// 不 NaN/不 ∞；actual 含一个 ⊤ 项 ⇒ 整体 DeviationVal.Top（§3.1.5c 跳过，不崩溃）。</summary>
    [Fact]
    public void LargeDeviation_NoCrash_And_TopWhenUnknown()
    {
        var res = new ResourceId.Memory(3);

        var expectedClaims = new Claim[SmallN];
        var actualClaims = new Claim[SmallN];
        for (int i = 0; i < SmallN; i++)
        {
            expectedClaims[i] = new Claim(Kind.Occupy, res, Mode.Create, GlobalScope, Interval.Exact(1));
            actualClaims[i] = new Claim(Kind.Occupy, res, Mode.Create, GlobalScope, Interval.Exact(1));
        }
        var expected = Signature.Of(expectedClaims);
        var actual = Signature.Of(actualClaims);

        var dev = SignatureDeviation.Calculate(expected, actual);
        Assert.False(dev.IsTop);              // §9.1 有限偏差
        Assert.False(double.IsNaN(dev.Value)); // 不 NaN
        Assert.False(double.IsInfinity(dev.Value)); // 不 ∞
        Assert.True(dev.Value < 1e-9);        // 同输入 ⇒ 偏差 ≈ 0

        // actual 含一个 ⊤ 项（Dynamic [1,⊤]）⇒ 该资源 TryMid 失败 ⇒ 整体 ⊤（§3.1.5c 跳过）
        var actualWithTop = new Claim[SmallN + 1];
        for (int i = 0; i < SmallN; i++)
            actualWithTop[i] = actualClaims[i];
        actualWithTop[SmallN] = new Claim(Kind.Occupy, res, Mode.Create, GlobalScope, Interval.Dynamic); // Hi=⊤
        var actualTopSig = Signature.Of(actualWithTop);

        var devTop = SignatureDeviation.Calculate(expected, actualTopSig);
        Assert.True(devTop.IsTop);            // §9.1/§3.1.5c：任一 ⊤ ⇒ 整体 ⊤（不崩溃、不报警）
    }

    /// <summary>§3.1.5a — 规模上限保护：溢出 ⇒ 保守 ⊤（不溢出到负）；非溢出大数仍有限且为正。</summary>
    [Fact]
    public void NatStar_Overflow_ConservativeTop()
    {
        // 溢出：MaxValue + 1 与 MaxValue * 2 均超出 ulong 范围 ⇒ 环绕检测 ⇒ ⊤ 保守
        Assert.True((NatStar.Of(ulong.MaxValue) + NatStar.Of(1)).IsTop);   // §3.1.5a 加溢出 ⇒ ⊤
        Assert.True((NatStar.Of(ulong.MaxValue) * NatStar.Of(2)).IsTop);   // §3.1.5a 乘溢出 ⇒ ⊤

        // 非溢出：MaxValue/2 + MaxValue/2 = 2^64-2，仍 ≤ MaxValue ⇒ 有限且为正（不溢出到负，证明守护有效）
        var big = NatStar.Of(ulong.MaxValue / 2) + NatStar.Of(ulong.MaxValue / 2);
        Assert.False(big.IsTop);
        Assert.True(big.Value > 0); // §3.1.5a：非负，不上溢到负
        Assert.Equal(ulong.MaxValue - 1, big.Value);
    }

    /// <summary>§3.3.1 — 性能软约束：N=5000 occupy 签名的 net 计算 < 2000ms（弱约束，非硬超时；超时仅记软失败）。</summary>
    [Fact]
    public void LargeSignature_Net_PerformanceSoftBudget()
    {
        var res = new ResourceId.Memory(4);
        var sig = BuildPureCreates(res, PerfN, UnitSize);

        var sw = Stopwatch.StartNew();
        var net = NetTable.Compute(sig, GlobalScope);
        sw.Stop();

        // 正确性保底（性能测试同时验证结果正确）
        Assert.False(net.IsConserved(res));

        // 性能软约束：宽松上界 2000ms；若超界仅作软失败（CI 弱约束，不硬阻塞，见 §3.3.1 性能注记）
        var elapsedMs = sw.ElapsedMilliseconds;
        Assert.True(elapsedMs < PerfBudgetMs,
            $"net 计算耗时 {elapsedMs}ms 超出软预算 {PerfBudgetMs}ms（性能回归预警，非硬失败）");
    }
}

